from contextlib import contextmanager
import copy
import fcntl
import json
import os
from pathlib import Path
import re
import secrets
import signal
import subprocess
import sys
import tempfile
import time

CANCELLED=None


class Invalid(Exception):pass
class Busy(Exception):pass


def cancel(signum,frame):
    global CANCELLED
    if CANCELLED is None:CANCELLED=signum


def ready_to_commit(expected_cancel):
    # Waiting for the state lock and writing/fsyncing a temporary file remain
    # cancellable. Only the final ready-to-replace decision is a short commit
    # section. If cancellation arrived during I/O, discard that temporary state
    # and calculate its outcome again from the unchanged locked base state.
    signal.signal(signal.SIGTERM,signal.SIG_IGN);signal.signal(signal.SIGINT,signal.SIG_IGN)
    if CANCELLED!=expected_cancel:
        signal.signal(signal.SIGTERM,cancel);signal.signal(signal.SIGINT,cancel)
        return False
    return True


def decimal(text,maximum):
    if not re.fullmatch('[0-9]+',text):raise Invalid()
    normalized=text.lstrip('0') or '0'
    if len(normalized)>10 or int(normalized,10)>maximum:raise Invalid()
    return int(normalized,10)


@contextmanager
def locked(wait=False):
    descriptor=os.open('.breaker.lock',os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW,0o600)
    try:
        deadline=time.monotonic()+(2 if wait else 0)
        while True:
            try:fcntl.flock(descriptor,fcntl.LOCK_EX|fcntl.LOCK_NB);break
            except BlockingIOError:
                if time.monotonic()>=deadline:raise Busy()
                time.sleep(.01)
        yield
    finally:os.close(descriptor)


def load():
    path=Path('breaker.json')
    if not os.path.lexists(path):return {'schema':1,'mode':'CLOSED','failures':0,'until':0,'generation':0,'last_now':-1,'probe':None}
    if path.is_symlink() or not path.is_file():raise Invalid()
    try:state=json.loads(path.read_text())
    except (ValueError,UnicodeError):raise Invalid() from None
    if not isinstance(state,dict) or set(state)!={'schema','mode','failures','until','generation','last_now','probe'}:raise Invalid()
    if type(state['schema']) is not int or state['schema']!=1 or state['mode'] not in ('CLOSED','OPEN','HALF_OPEN'):raise Invalid()
    if any(type(state[key]) is not int for key in ('failures','until','generation','last_now')):raise Invalid()
    if not 0<=state['failures']<=3 or not 0<=state['until']<=1000000010 or not 0<=state['generation']<=1000000000 or not -1<=state['last_now']<=1000000000:raise Invalid()
    if state['mode']=='CLOSED':
        if state['failures']>=3 or state['until']!=0 or state['probe'] is not None:raise Invalid()
    elif state['failures']!=3 or state['until']<10:raise Invalid()
    if state['mode']=='HALF_OPEN':
        if not isinstance(state['probe'],str) or not re.fullmatch('[0-9a-f]{24}',state['probe']):raise Invalid()
    elif state['probe'] is not None:raise Invalid()
